namespace Kit.CodeShape.Tests;

public sealed class ProjectCheckTests : IDisposable
{
    private const string DeepClass =
        "class Deep { void Run(int a) { if (a > 0) { if (a > 1) { if (a > 2) { if (a > 3) { if (a > 4) { a++; } } } } } } }";

    private readonly DirectoryInfo _folder = Directory.CreateTempSubdirectory("codeshape-");

    public void Dispose() => _folder.Delete(recursive: true);

    // The compiler's own test for generated code, which its analyzers skip too: the file's name, or an
    // <auto-generated> comment at its top. Only EF Core's migration files may be marked (GeneratedMarkerRule), which
    // these aren't, so only the limits' findings count here.
    [Theory]
    [InlineData("Deep.g.cs", "")]
    [InlineData("Deep.g.i.cs", "")]
    [InlineData("Deep.generated.cs", "")]
    [InlineData("Deep.Designer.cs", "")]
    [InlineData("TemporaryGeneratedFile_Deep.cs", "")]
    [InlineData("Deep.cs", "// <auto-generated/>\n")]
    [InlineData("Deep.cs", "// <auto-generated>\n// Made by a tool.\n// </auto-generated>\n")]
    public void GeneratedFilesAreSkipped(string name, string header)
    {
        string path = Write(name, header + DeepClass);

        ProjectCheck.Check(new ProjectFiles("App.csproj", [], [path])).Where(finding => finding.Rule == RuleCodes.Shape).Should().BeEmpty();
    }

    [Fact]
    public void AFileWithAnAutoGeneratedCommentFurtherDownIsStillChecked()
    {
        string path = Write("Deep.cs", "// Written by hand.\n" + DeepClass + "\n// <auto-generated/>\n");

        ProjectCheck.Check(new ProjectFiles("App.csproj", [], [path])).Should().ContainSingle();
    }

    [Theory]
    [InlineData(new string[0], 0)]
    [InlineData(new[] { "KIT_DEEP" }, 1)]
    public void CodeIsReadWithTheProjectsPreprocessorSymbols(string[] defines, int findings)
    {
        string path = Write("Deep.cs", $"#if KIT_DEEP\n{DeepClass}\n#endif\n");

        ProjectCheck.Check(new ProjectFiles("App.csproj", defines, [path])).Should().HaveCount(findings);
    }

    // Every limit reports, and findings come in path, line and column order, whatever order the files came in.
    [Fact]
    public void EveryLimitReportsInPathLineAndColumnOrder()
    {
        string f = Write("F.cs", "class Wide { " + string.Concat(Enumerable.Range(0, 21).Select(i => $"void M{i}() {{ }} ")) + "}");
        string e = Write("E.cs", "public class One { } public class Two { }");
        string d = Write("D.cs", string.Join('\n', Enumerable.Repeat("// a line", 401)));
        string c = Write("C.cs", "class Long { void Run(int a) { " + string.Concat(Enumerable.Repeat("a++; ", 31)) + "} }");
        string b = Write("B.cs", DeepClass);
        string a = Write("A.cs", string.Join('\n',
            "class Ledger { private int _a; private int _b; void A() => _a++; void B() { if (_b > 0) { if (_b > 1) { if (_b > 2) { if (_b > 3) { if (_b > 4) { _b++; } } } } } } }",
            "",
            DeepClass.Replace("class Deep", "class Deeper", StringComparison.Ordinal)));

        IEnumerable<string> found = ProjectCheck.Check(new ProjectFiles("App.csproj", [], [f, e, d, c, b, a]))
            .Select(finding => $"{Path.GetFileName(finding.Path)}:{finding.Line}:{string.Join(' ', finding.Message.Split(' ').Take(2))}");

        found.Should().Equal("A.cs:1:Ledger's methods", "A.cs:1:B nests", "A.cs:3:Run nests", "B.cs:1:Run nests", "C.cs:1:Run has", "D.cs:401:The file", "E.cs:1:The file", "F.cs:1:Wide has");
    }

    // STY-005: the nullable rules run on every hand-written file, and the marker rule on every generated one.
    [Fact]
    public void TheNullableRulesReportOnHandWrittenFilesAndTheMarkerRuleOnGeneratedOnes()
    {
        string legacy = Write("Legacy.cs", "#nullable disable\nclass Legacy { string? _a; int N() => _a!.Length; }\n");
        string marked = Write("Marked.g.cs", "class Marked { }");

        IEnumerable<string> found = ProjectCheck.Check(new ProjectFiles("App.csproj", [], [legacy, marked]))
            .Select(finding => $"{Path.GetFileName(finding.Path)}:{finding.Line}:{finding.Rule}");

        found.Should().Equal("Legacy.cs:1:STY005", "Legacy.cs:2:STY005", "Marked.g.cs:1:STY005");
    }

    // The owner, 2026-11-16 ("exempt tests"): a test's ! follows an assertion that checked the value, or passes null on
    // purpose to test a guard, so a test project (a name ending in Tests, as STY-015 and CA2007 have it) needs no label.
    // A #nullable directive is still reported there.
    [Fact]
    public void ATestProjectMayUseTheNullForgivingOperatorUnlabelledButNotNullableDirectives()
    {
        string tests = Write("GuardTests.cs", "#nullable disable\nclass GuardTests { void Run() => Guard(null!); void Guard(string s) { } }\n");

        ProjectCheck.Check(new ProjectFiles(Path.Join("tests", "Widgets.Tests", "Widgets.Tests.csproj"), [], [tests]))
            .Should().ContainSingle().Which.Line.Should().Be(1);
    }

    // Review 1: a .resx file's designer is generated by the resource tools beside it, and kept in source.
    [Fact]
    public void AResourceFilesDesignerMayBeMarkedGenerated()
    {
        Write("Strings.resx", "<root />");
        string designer = Write("Strings.Designer.cs", "// <auto-generated>\n// Made by the resource generator.\n// </auto-generated>\nclass Strings { }\n");

        ProjectCheck.Check(new ProjectFiles("App.csproj", [], [designer])).Should().BeEmpty();
    }

    // Review 2: only a Migrations folder inside the project counts, not one the repo happens to sit in.
    [Fact]
    public void AFolderNamedMigrationsAboveTheProjectExemptsNothing()
    {
        // EF Core's own names, so only where the folder sits decides.
        string legacy = Write(Path.Join("Migrations", "App", "20261116000000_Legacy.cs"), "#nullable disable\nclass Legacy { }\n");
        string marked = Write(Path.Join("Migrations", "App", "20261116000000_Marked.Designer.cs"), "class Marked { }");

        ProjectCheck.Check(new ProjectFiles(Path.Join(_folder.FullName, "Migrations", "App", "App.csproj"), [], [legacy, marked]))
            .Should().HaveCount(2);
    }

    private string Write(string name, string text)
    {
        string path = Path.Join(_folder.FullName, name);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!); // CRF-001 safety net: the path is a file in the temp folder, so it has one.
        File.WriteAllText(path, text);
        return path;
    }
}
